version='portrait_v2';metrics=load(f'qa/{version}_metrics.json');portrait=metrics['candidate']['path'];held=review['decision'].startswith('held')
files=[{'path':str(p.relative_to(W)),'bytes':p.stat().st_size,'sha256':sha(p)} for p in sorted(W.rglob('*')) if p.is_file() and p.name not in ['manifest.json','SHA256SUMS']]
manifest={'schema_version':1,'actor_id':entry['canonical_id'],'name':entry['name'],'date':'2026-10-15','status':review['decision'],'selected_portrait':None if held else portrait,'selected_sha256':None if held else sha(W/portrait),'held_evidence_portrait':portrait if held else None,'held_evidence_sha256':sha(W/portrait) if held else None,'deliverable_approved':not held,'exclude_from_pass_gallery':held,'generation_calls':2,'max_imagegen_calls':2,'native_authored':False,'native_pixel_approved':False,'runtime_integrated':False,'runtime_verified':False,'old_assets_preserved':True,'tool':'image_gen.imagegen built-in','model_size_quality_seed':'Not exposed; no fabricated values.','method':'Substantive built-in imagegen redraw; full-canvas aspect-preserving NEAREST fit to 74x100; alpha threshold 128; temporary <=32 visible-color MAXCOVERAGE with no dithering. No script draws facial geometry. This is a technical derivative candidate, not native pixel final.','color_budget_note':'Temporary working ceiling, not native pixel art approval.','source_manifest':'sources/source_manifest.json','spec_lock':'spec_lock.md','author_visual_review':'qa/author_visual_review.json','independent_review':'qa/independent_review_acceptance.json','independent_batch_review':'../independent_qa/batch24/','raw_margin_audit':'qa/raw_margin_audit.json','source_integrity':'qa/source_hash_recheck.json','reproduction_audit':'qa/reproducibility.json','reproduction':['python derive_portrait.py portrait_v1','python derive_portrait.py portrait_v2','python finalize_manifest.py'],'assets':[load(str(p.relative_to(W))) for p in sorted((W/'qa').glob('portrait*_metrics.json'))],'limitations':review['limitations'],'raw_provenance':[{'version':v,'raw_path':f'raw/{v}_raw_imagegen.png','raw_sha256':sha(W/f'raw/{v}_raw_imagegen.png'),'full_tool_return_path':f'tool_returns/{v}.json','full_tool_return_sha256':sha(W/f'tool_returns/{v}.json'),'actual_arguments_path':f'prompts/{v}.json','raw_equals_decoded_return':load(f'qa/{v}_metrics.json')['raw']['byte_identical_to_full_tool_return']} for v in ['portrait_v1','portrait_v2']],'files':files}
if held: manifest['hold_reason']='Composition/scale: near-square generated source has only 69 target visible rows and oversized side-bun footprint; target right-edge contact from insufficient source margin; eye whites remain bright. Closed source silhouette with 6/7px alpha>=128 right margin is documented, so confirmed source clipping is NOT the gate.'
(W/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
all_files=[p for p in sorted(W.rglob('*')) if p.is_file() and p.name!='SHA256SUMS']
(W/'SHA256SUMS').write_text(''.join(f'{sha(p)}  {p.relative_to(W)}\n' for p in all_files))
print(entry['name'],manifest['status'],manifest['selected_portrait'],manifest['held_evidence_portrait'])

